:root {
    --bg: #0a0a0a;
    --bg-elevated: #141414;
    --primary: #e63946;
    --accent: #ff69b4;
    --text: #d4d4d4;
    --muted: #808080;
    --success: #10b981;
    font-size: 16px;
}

@media (prefers-color-scheme: dark) {
    :root {
        --bg: #0a0a0a;
        --bg-elevated: #141414;
    }
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}



body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Helvetica Neue', sans-serif;
    background: var(--bg);
    
    color: var(--text);
    line-height: 1.6;
    letter-spacing: -0.02em;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
    text-transform: uppercase;
    letter-spacing: -0.03em;
    font-weight: 700;
    line-height: 1.2;
}

h1 { font-size: 4rem; }
h2 { font-size: 2.5rem; }
h3 { font-size: 1.75rem; }
h4 { font-size: 1.25rem; }
p { margin-bottom: 1.5rem; }

/* Container & Layout */
.site-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 2rem;
}

.section {
    padding: 6rem 0;
    border-bottom: 1px solid rgba(255,255,255,0.05);
}

.section:last-child {
    border-bottom: none;
}

.section-title {
    font-size: 2.5rem;
    text-transform: uppercase;
    letter-spacing: -0.03em;
    margin-bottom: 3rem;
    color: var(--primary);
    position: relative;
    padding-bottom: 1rem;
    cursor: default;
        display: inline-block;
}

.section-title::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 60px;
    height: 3px;
    background: var(--primary);
    transition: width 0.3s;
    }
    
    .section-title:hover::after {
        width: 100%;
}

/* Header */
header {
    position: fixed;
    top: 0;
    left: 0;
        right: 0;
    z-index: 1000;
    background: transparent;
    padding: 1.5rem 0;
    pointer-events: none;
    }
    
    .header-content {
        pointer-events: auto;
}

.header-content {
    display: flex;
    justify-content: center;
    align-items: center;
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 2rem;
}

.logo {
    font-size: 1.5rem;
    font-weight: 900;
    text-transform: uppercase;
    letter-spacing: -0.02em;
    color: var(--text);
    text-decoration: none;
}

.logo:hover {
    color: var(--primary);
}

nav {
    display: flex;
    gap: 0.5rem;
    align-items: center;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(230, 57, 70, 0.3);
        border-radius: 50px;
        padding: 0.5rem;
        backdrop-filter: blur(10px);
}

.nav-link {
    text-decoration: none;
    color: var(--text);
    font-family: 'Space Grotesk', sans-serif;
    font-weight: 500;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.02em;
    position: relative;
    display: flex;
        align-items: center;
        gap: 0;
        padding: 0.6rem;
        border-radius: 50px;
        transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        overflow: hidden;
    cursor: pointer;
}

.nav-link svg {
    flex-shrink: 0;
    transition: all 0.3s ease;
}

.nav-link span {
    max-width: 0;
    opacity: 0;
    white-space: nowrap;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Expand on hover */
nav:hover .nav-link span {
    max-width: 100px;
    opacity: 1;
    margin-right: 0.25rem;
}

nav:hover .nav-link {
    padding: 0.6rem 1rem;
    gap: 0.5rem;
}

.nav-link:hover {
    color: var(--primary);
    background: rgba(230, 57, 70, 0.15);
}

.nav-link:hover svg {
    filter: drop-shadow(0 0 8px rgba(230, 57, 70, 0.6));
}

/* Active link indicator - only show when nav is not hovered */
.nav-link.active {
    color: var(--primary);
    background: rgba(230, 57, 70, 0.15);
}

.nav-link.active svg {
    filter: drop-shadow(0 0 8px rgba(230, 57, 70, 0.6));
}

/* When hovering nav, remove active styling from non-hovered links */
nav:hover .nav-link.active {
    color: var(--text);
    background: transparent;
}

nav:hover .nav-link.active svg {
    filter: none;
}

/* Re-apply active styling when hovering the active link itself */
nav:hover .nav-link.active:hover {
    color: var(--primary);
    background: rgba(230, 57, 70, 0.15);
}

nav:hover .nav-link.active:hover svg {
    filter: drop-shadow(0 0 8px rgba(230, 57, 70, 0.6));
}
.hamburger {
    display: none;
    flex-direction: column;
    gap: 6px;
    cursor: pointer;
    background: none;
    border: none;
    padding: 0;
}

.hamburger span {
    width: 24px;
    height: 2px;
    background: var(--text);
    transition: all 0.3s;
}

.hamburger.open span:nth-child(1) {
    transform: rotate(45deg) translate(8px, 8px);
}

.hamburger.open span:nth-child(2) {
    opacity: 0;
}

.hamburger.open span:nth-child(3) {
    transform: rotate(-45deg) translate(7px, -6px);
}

/* Hero */
.hero {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    text-align: center;
    position: relative;
    overflow: hidden;
    padding: 4rem 2rem;
}

.hero::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(to bottom, rgba(230, 57, 70, 0.05) 0%, rgba(230, 57, 70, 0.025) 50%, transparent 100%);
        pointer-events: none;
    }
/* Floating Particles */
.hero-particles {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    overflow: hidden;
    pointer-events: none;
}

.particle {
    position: absolute;
    width: 6px;
    height: 6px;
    background: var(--primary);
    border-radius: 50%;
    opacity: 0.4;
    animation: float 15s infinite ease-in-out;
}

.particle:nth-child(1) {
    left: 10%;
    top: 20%;
    animation-delay: 0s;
    animation-duration: 12s;
}

.particle:nth-child(2) {
    left: 20%;
    top: 80%;
    animation-delay: 2s;
    animation-duration: 14s;
}

.particle:nth-child(3) {
    left: 60%;
    top: 40%;
    animation-delay: 4s;
    animation-duration: 13s;
}

.particle:nth-child(4) {
    left: 80%;
    top: 60%;
    animation-delay: 1s;
    animation-duration: 16s;
}

.particle:nth-child(5) {
    left: 35%;
    top: 90%;
    animation-delay: 3s;
    animation-duration: 11s;
}

.particle:nth-child(6) {
    left: 90%;
    top: 15%;
    animation-delay: 5s;
    animation-duration: 15s;
}

@keyframes float {

    0%,
    100% {
        transform: translateY(0) translateX(0) scale(1);
        opacity: 0.4;
    }

    25% {
        transform: translateY(-30px) translateX(15px) scale(1.2);
        opacity: 0.6;
    }

    50% {
        transform: translateY(-10px) translateX(-10px) scale(0.8);
        opacity: 0.3;
    }

    75% {
        transform: translateY(-40px) translateX(5px) scale(1.1);
        opacity: 0.5;
    }
}

/* Hero Badge */
.hero-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 1.25rem;
    background: rgba(230, 57, 70, 0.1);
    border: 1px solid rgba(230, 57, 70, 0.3);
    border-radius: 50px;
    font-size: 0.85rem;
    color: var(--primary);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    font-weight: 600;
    margin-bottom: 2rem;
    animation: badge-pulse 3s ease-in-out infinite;
}

.pulse-dot {
    width: 8px;
    height: 8px;
    background: #10b981;
    border-radius: 50%;
    animation: pulse 2s ease-in-out infinite;
}

@keyframes pulse {

    0%,
    100% {
        transform: scale(1);
        box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.5);
    }

    50% {
        transform: scale(1.1);
        box-shadow: 0 0 0 8px rgba(16, 185, 129, 0);
    }
}

@keyframes badge-pulse {

    0%,
    100% {
        box-shadow: 0 0 20px rgba(230, 57, 70, 0.1);
    }

    50% {
        box-shadow: 0 0 30px rgba(230, 57, 70, 0.2);
    }
}

.hero-title {
    font-size: clamp(3rem, 12vw, 7rem);
    margin-bottom: 1rem;
    color: var(--text);
    line-height: 1;
        display: flex;
        flex-direction: column;
        gap: 0.25rem;
    }
    
    .hero-title-line {
        display: block;
        font-weight: 300;
        letter-spacing: -0.04em;
    }
    
    .hero-title-accent {
        display: block;
        font-weight: 900;
        color: var(--primary);
        text-shadow: 0 0 40px rgba(230, 57, 70, 0.4);
}

.hero-subtitle {
    font-size: 1.5rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.1em;
        margin-bottom: 1.5rem;
        font-weight: 500;
}

.hero-tagline {
    font-size: 1.15rem;
    color: var(--muted);
    margin-bottom: 3rem;
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
    line-height: 1.9;
        font-style: normal;
}

.hero-buttons {
    display: flex;
    gap: 1.5rem;
    justify-content: center;
    flex-wrap: wrap;
    margin-bottom: 4rem;
    }
    
    .btn-glow {
        animation: btn-glow 2s ease-in-out infinite;
    }
    
    @keyframes btn-glow {
    
        0%,
        100% {
            box-shadow: 0 0 20px rgba(230, 57, 70, 0.3);
        }
    
        50% {
            box-shadow: 0 0 35px rgba(230, 57, 70, 0.5);
        }
    }
    
    .btn svg {
        display: inline-block;
        vertical-align: middle;
    }
    
    .btn span {
        display: inline-block;
        vertical-align: middle;
    }
    
    .btn-primary {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
    }
    
    /* Hero Stats */
    .hero-stats {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 2rem;
        padding: 1.5rem 3rem;
        background: rgba(20, 20, 20, 0.8);
        border: 1px solid rgba(255, 255, 255, 0.1);
        backdrop-filter: blur(10px);
    }
    
    .stat-item {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 0.25rem;
    }
    
    .stat-value {
        font-size: 2rem;
        font-weight: 900;
        color: var(--primary);
        letter-spacing: -0.02em;
    }
    
    .stat-label {
        font-size: 0.75rem;
        text-transform: uppercase;
        letter-spacing: 0.1em;
        color: var(--muted);
        font-weight: 600;
    }
    
    .stat-divider {
        width: 1px;
        height: 40px;
        background: rgba(255, 255, 255, 0.1);
    }
    
    /* Hero Glow Effects */
    .hero-glow {
        position: absolute;
        top: 20%;
        left: 50%;
        transform: translateX(-50%);
        width: 600px;
        height: 600px;
        background: radial-gradient(circle, rgba(230, 57, 70, 0.15) 0%, transparent 70%);
        pointer-events: none;
        z-index: -1;
    }
    
    .hero-glow-2 {
        position: absolute;
        bottom: 10%;
        right: 10%;
        width: 400px;
        height: 400px;
        background: radial-gradient(circle, rgba(255, 105, 180, 0.08) 0%, transparent 70%);
        pointer-events: none;
        z-index: -1;
}

/* Buttons */
.btn {
    padding: 1rem 2.5rem;
    font-size: 0.95rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: -0.01em;
    border: 2px solid var(--primary);
    background: transparent;
    color: var(--text);
    cursor: pointer;
    transition: all 0.3s;
    text-decoration: none;
    display: inline-block;
    position: relative;
    overflow: hidden;
}

.btn:hover {
    background: var(--primary);
    color: var(--bg);
    transform: skewX(-2deg) scaleY(1.05);
    box-shadow: 0 0 20px rgba(230, 57, 70, 0.4);
}

.btn-primary {
    background: var(--primary);
    color: var(--bg);
    border-color: var(--primary);
}

.btn-primary:hover {
    background: transparent;
    color: var(--text);
}

/* About Section */
#about {
    position: relative;
    overflow: hidden;
}
.about-layout {
    display: grid;
    grid-template-columns: 300px 1fr;
    gap: 4rem;
    align-items: start;
}

/* Profile Card - Enhanced with Glow & Halo */
.profile-card {
    background: linear-gradient(145deg, rgba(18, 18, 20, 0.95) 0%, rgba(28, 28, 32, 0.9) 100%);
        border: 1px solid rgba(230, 57, 70, 0.2);
        border-radius: 20px;
        padding: 2.5rem 2rem;
    text-align: center;
    position: relative;
    overflow: visible;
        transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
        animation: card-float 6s ease-in-out infinite;
    }
        @keyframes card-float {
    
            0%,
            100% {
                transform: translateY(0);
            }
    
            50% {
                transform: translateY(-8px);
            }
        }
    
        /* Animated Border Glow */
    
        .profile-card:hover {
            transform: translateY(-12px) scale(1.02);
            border-color: var(--primary);
            box-shadow:
                0 0 30px rgba(230, 57, 70, 0.5),
                0 0 60px rgba(230, 57, 70, 0.3),
                0 0 100px rgba(230, 57, 70, 0.2),
                0 25px 50px rgba(0, 0, 0, 0.4);
        }
    
        .profile-card:hover::before {
            opacity: 0.9;
            filter: blur(12px);
}

.profile-image-wrapper {
    position: relative;
    width: 150px;
        height: 150px;
        margin: 0 auto 1.75rem;
    z-index: 1;
}

.profile-image {
    width: 100%;
    height: 100%;
    border-radius: 50%;
    object-fit: cover;
    border: 4px solid transparent;
        background: linear-gradient(var(--bg), var(--bg)) padding-box,
            linear-gradient(135deg, var(--primary), #e639464d) border-box;
        box-shadow:
            0 0 40px rgba(230, 57, 70, 0.4),
            0 0 80px rgba(230, 57, 70, 0.2);
        transition: all 0.4s ease;
}

/* Multi-layer Glow Effect */
.profile-image-glow {
    position: absolute;
    top: -15px;
        left: -15px;
        right: -15px;
        bottom: -15px;
    border-radius: 50%;
    background:
            radial-gradient(circle, rgba(230, 57, 70, 0.4) 0%, transparent 50%),
            radial-gradient(circle, rgba(255, 105, 180, 0.3) 20%, transparent 60%);
        animation: multi-glow 4s ease-in-out infinite;
    z-index: -1;
}

@keyframes multi-glow {

    0%,
    100% {
        opacity: 0.6;
            transform: scale(1) rotate(0deg);
    }

    50% {
        opacity: 1;
            transform: scale(1.15) rotate(180deg);
        }
        }
        
        
        .profile-image-wrapper::before {
            animation: orbit 3s linear infinite;
        }
        
        .profile-image-wrapper::after {
            animation: orbit 3s linear infinite reverse;
            animation-delay: -1.5s;
            background: #ff69b4;
            box-shadow: 0 0 15px #ff69b4;
        }
        
        @keyframes orbit {
            0% {
                transform: rotate(0deg) translateX(90px) rotate(0deg);
            }
        
            100% {
                transform: rotate(360deg) translateX(90px) rotate(-360deg);
    }
}

.profile-name {
    font-family: 'Space Grotesk', sans-serif;
        font-size: 1.75rem;
    font-weight: 700;
    color: #fff;
        margin-bottom: 0.5rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
        text-shadow: 0 0 30px rgba(230, 57, 70, 0.5);
}

.profile-title {
    font-family: 'Space Grotesk', sans-serif;
        font-size: 0.95rem;
    color: var(--primary);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 1rem;
}

.profile-location {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    font-family: 'Space Grotesk', sans-serif;
        font-size: 0.9rem;
    color: var(--muted);
    margin-bottom: 1.25rem;
    padding: 0.5rem 1rem;
        background: rgba(255, 255, 255, 0.03);
        border-radius: 30px;
        border: 1px solid rgba(255, 255, 255, 0.08);
}

.profile-location svg {
    color: var(--primary);
    filter: drop-shadow(0 0 5px rgba(230, 57, 70, 0.5));
    }
    
    /* Profile Stats */
    .profile-stats {
        display: flex;
        justify-content: center;
        gap: 1.5rem;
        margin-bottom: 1.25rem;
        padding: 1rem 0;
        border-top: 1px solid rgba(255, 255, 255, 0.08);
        border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    }
    
    .profile-stat {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 0.25rem;
    }
    
    .profile-stat .stat-number {
        font-family: 'Space Grotesk', sans-serif;
        font-size: 1.5rem;
        font-weight: 700;
        color: var(--primary);
        text-shadow: 0 0 20px rgba(230, 57, 70, 0.4);
    }
    
    .profile-stat .stat-label {
        font-family: 'Space Grotesk', sans-serif;
        font-size: 0.7rem;
        text-transform: uppercase;
        letter-spacing: 0.1em;
        color: var(--muted);
    }
    
    /* Current Focus */
    .current-focus {
        display: inline-flex;
        align-items: center;
        padding: 0.6rem 1rem;
        background: rgba(230, 57, 70, 0.1);
        border: 1px solid rgba(230, 57, 70, 0.25);
        border-radius: 8px;
        font-family: 'Space Grotesk', sans-serif;
        font-size: 0.8rem;
        color: var(--text);
        transition: all 0.3s ease;
    }
    
    .current-focus:hover {
        background: rgba(230, 57, 70, 0.15);
        border-color: var(--primary);
        transform: translateY(-2px);
        box-shadow: 0 4px 15px rgba(230, 57, 70, 0.2);
}

.profile-status {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 1.25rem;
    background: rgba(16, 185, 129, 0.1);
    border: 1px solid rgba(16, 185, 129, 0.3);
    border-radius: 50px;
    font-family: 'Space Grotesk', sans-serif;
        font-size: 0.85rem;
    color: #10b981;
    font-weight: 600;
    box-shadow: 0 0 20px rgba(16, 185, 129, 0.2);
}

.status-dot {
    width: 8px;
    height: 8px;
    background: #10b981;
    border-radius: 50%;
    animation: pulse 2s ease-in-out infinite;
    box-shadow: 0 0 10px #10b981;
}

/* About Content - Enhanced Typography */
.about-content {
    display: flex;
    flex-direction: column;
    gap: 2.5rem;
        position: relative;
    }
    
    .about-text {
        position: relative;
        padding-left: 1.5rem;
        border-left: 3px solid;
        border-image: linear-gradient(180deg, var(--primary), #ff69b4, transparent) 1;
}
.about-text p {
    font-family: 'Space Grotesk', sans-serif;
        font-size: 1.15rem;
        color: rgba(255, 255, 255, 0.9);
        line-height: 2;
        letter-spacing: 0.01em;
        margin-bottom: 1.75rem;
    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .about-text p:last-child {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    margin-bottom: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
.highlights {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
}

.highlight-tag {
    display: inline-flex;
    align-items: center;
    padding: 0.75rem 1.5rem;
        background: rgba(230, 57, 70, 0.08);
        border: 1px solid rgba(230, 57, 70, 0.25);
    border-radius: 50px;
    color: var(--text);
    font-family: 'Space Grotesk', sans-serif;
        font-size: 0.9rem;
        font-weight: 500;
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
        white-space: nowrap;
    position: relative;
        overflow: hidden;
    }
    
    /* Shimmer Effect on Tags */
    .highlight-tag::before {
        content: '';
        position: absolute;
        top: 0;
        left: -100%;
        width: 100%;
        height: 100%;
        background: linear-gradient(90deg,
                transparent,
                rgba(255, 255, 255, 0.1),
                transparent);
        transition: left 0.5s ease;
    }
    
    .highlight-tag:hover::before {
        left: 100%;
}

.highlight-tag:hover {
    background: rgba(230, 57, 70, 0.2);
    border-color: var(--primary);
    transform: translateY(-4px) scale(1.05);
        box-shadow:
            0 8px 25px rgba(230, 57, 70, 0.3),
            0 0 40px rgba(230, 57, 70, 0.15);
        color: #fff;
    }
    
    /* Staggered Animation for Tags */
    .highlight-tag:nth-child(1) {
        animation: tag-pop 0.5s ease 0.1s both;
    }
    
    .highlight-tag:nth-child(2) {
        animation: tag-pop 0.5s ease 0.2s both;
    }
    
    .highlight-tag:nth-child(3) {
        animation: tag-pop 0.5s ease 0.3s both;
    }
    
    .highlight-tag:nth-child(4) {
        animation: tag-pop 0.5s ease 0.4s both;
    }
    
    .highlight-tag:nth-child(5) {
        animation: tag-pop 0.5s ease 0.5s both;
    }
    
    @keyframes tag-pop {
        0% {
            opacity: 0;
            transform: translateY(20px) scale(0.8);
        }
    
        100% {
            opacity: 1;
            transform: translateY(0) scale(1);
        }
}

/* Projects - Stacked Cards */
.projects-grid {
    display: flex;
    flex-direction: column;
        gap: 0;
        max-width: 800px;
        margin: 0 auto;
    position: relative;
}

.project-card {
    position: sticky;
        top: 100px;
        width: 100%;
        min-height: 400px;
        background: linear-gradient(145deg, rgba(18, 18, 20, 0.98) 0%, rgba(28, 28, 32, 0.95) 100%);
        border: 1px solid rgba(230, 57, 70, 0.2);
        border-radius: 20px;
        padding: 2.5rem 3rem;
        transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
    display: flex;
    flex-direction: column;
    overflow: hidden;
        box-shadow: 0 -10px 40px rgba(0, 0, 0, 0.5);
        margin-bottom: 40px;
}

.project-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, rgba(230, 57, 70, 0.08) 0%, transparent 50%);
    opacity: 0;
    transition: opacity 0.4s ease;
    pointer-events: none;
}

.project-card:nth-child(1) {
    top: 100px;
    z-index: 1;
}

.project-card:nth-child(2) {
    top: 120px;
    z-index: 2;
}

.project-card:nth-child(3) {
    top: 140px;
    z-index: 3;
}

.project-card:nth-child(4) {
    top: 160px;
    z-index: 4;
}

.project-card:nth-child(5) {
    top: 180px;
    z-index: 5;
}
.project-card:hover {
    border-color: rgba(54, 2, 5, 0.133);
        transform: scale(1.02);
        box-shadow:
            0 -10px 60px rgba(0, 0, 0, 0.6),
        0 0 60px rgba(100, 7, 15, 0.2),
            inset 0 0 30px rgba(230, 57, 70, 0.05);
        }
        
        .project-card:hover::before {
            opacity: 1;
}

/* Animated border glow on hover */
.project-card::after {
    content: '';
    position: absolute;
    top: -2px;
    left: -2px;
    right: -2px;
    bottom: -2px;
    background: linear-gradient(45deg,
            transparent 0%,
            rgba(46, 2, 6, 0.217) 25%,
            rgba(79, 3, 8, 0.661) 50%,
            rgba(53, 13, 17, 0.3) 75%,
            transparent 100%);
    background-size: 400% 400%;
    border-radius: 22px;
    z-index: -1;
    opacity: 0;
    transition: opacity 0.4s ease;
}

.project-card:hover::after {
    opacity: 1;
    animation: borderGlow 3s ease infinite;
}

@keyframes borderGlow {

    0%,
    100% {
        background-position: 0% 50%;
    }

    50% {
        background-position: 100% 50%;
    }
}
.project-name {
    font-family: 'Space Grotesk', sans-serif;
    font-size: 1.75rem;
        margin-bottom: 1.25rem;
        color: #fff;
    font-weight: 700;
    display: flex;
        align-items: center;
    gap: 1rem;
    text-transform: uppercase;
        letter-spacing: 0.02em;
    transition: text-shadow 0.3s ease;
}

.project-name::before {
    content: '';
    width: 14px;
    height: 14px;
        background: var(--primary);
        border-radius: 50%;
        flex-shrink: 0;
    box-shadow: 0 0 16px rgba(230, 57, 70, 0.7);
    transition: all 0.3s ease;
    }
.project-card:hover .project-name {
    text-shadow: 0 0 20px rgba(230, 57, 70, 0.4);
}

.project-card:hover .project-name::before {
    box-shadow: 0 0 30px rgba(230, 57, 70, 1);
    transform: scale(1.3);
    animation: pulse 1.5s ease-in-out infinite;
}
    
        @keyframes pulse {
    
            0%,
            100% {
                box-shadow: 0 0 20px rgba(230, 57, 70, 1);
                transform: scale(1.3);
            }
    
            50% {
                box-shadow: 0 0 40px rgba(230, 57, 70, 0.6);
                transform: scale(1.1);
            }
}

.project-desc {
    font-family: 'Space Grotesk', sans-serif;
        color: rgba(255, 255, 255, 0.75);
        margin-bottom: 2rem;
        font-size: 1.1rem;
        line-height: 1.8;
    flex-grow: 1;
    letter-spacing: 0.01em;
}

.project-stack {
    display: flex;
    flex-wrap: wrap;
    gap: 0.6rem;
        margin-bottom: 2rem;
}

.stack-tag {
    display: inline-block;
    padding: 0.5rem 1rem;
        background: rgba(230, 57, 70, 0.1);
    color: var(--primary);
    font-family: 'Space Grotesk', sans-serif;
        font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
        border-radius: 50px;
        font-weight: 600;
        border: 1px solid rgba(230, 57, 70, 0.25);
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    }
    
    .stack-tag:hover {
    background: rgba(230, 57, 70, 0.2);
        border-color: var(--primary);
    transform: translateY(-2px);
}

.project-links {
    display: flex;
    gap: 1rem;
        margin-top: auto;
}

.project-links a {
    flex: 0 1 200px;
        padding: 1rem 1.5rem;
        background: rgba(255, 255, 255, 0.03);
    color: rgba(255, 255, 255, 0.9);
        border: 1px solid rgba(255, 255, 255, 0.15);
        border-radius: 12px;
    text-decoration: none;
    font-family: 'Space Grotesk', sans-serif;
        font-size: 0.9rem;
        font-weight: 600;
    text-transform: uppercase;
    text-align: center;
    letter-spacing: 0.06em;
        transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.project-links a:hover {
    background: var(--primary);
    border-color: var(--primary);
    color: #fff;
    transform: translateY(-3px);
        box-shadow: 0 10px 30px rgba(230, 57, 70, 0.4);
}
@media (max-width: 768px) {
    .projects-grid {
        max-width: 100%;
            padding: 0 1rem;
    }
    
        .project-card {
            min-height: auto;
            padding: 1.75rem 1.5rem;
            margin-bottom: 30px;
        }
        .project-name {
            font-size: 1.35rem;
        }
        .project-desc {
            font-size: 1rem;
        }
        .project-links {
            flex-direction: column;
        }
    
        .project-links a {
            flex: 1;
        }
}

/* Socials */
.socials-wrapper {
    max-width: 900px;
    margin: 0 auto;
    text-align: center;
}

.socials-tagline {
    font-family: 'Space Grotesk', sans-serif;
        font-size: 1.1rem;
    color: var(--muted);
    margin-bottom: 3rem;
    letter-spacing: 0.02em;
}

.socials-grid {
    display: flex;
        justify-content: center;
        gap: 3rem;
        flex-wrap: wrap;
}

.social-card {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 1rem;
        background: transparent;
        border: none;
        text-decoration: none;
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
        position: relative;
}

.social-card:hover {
    transform: translateY(-8px);
}

.social-icon {
    width: 52px;
        height: 52px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 0.75rem;
    color: var(--primary);
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.social-icon svg {
    width: 100%;
    height: 100%;
}

.social-card:hover .social-icon {
    color: var(--primary);
        transform: scale(1.2);
        filter: drop-shadow(0 0 15px rgba(230, 57, 70, 0.6));
}

.social-label {
    font-family: 'Space Grotesk', sans-serif;
        font-size: 0.9rem;
        font-weight: 600;
    text-transform: uppercase;
    color: var(--text);
    margin-bottom: 0.25rem;
        letter-spacing: 0.05em;
        transition: color 0.3s ease;
    }
    
    .social-card:hover .social-label {
        color: var(--primary);
}

.social-handle {
    font-family: 'Space Grotesk', sans-serif;
        font-size: 0.8rem;
    color: var(--muted);
    transition: color 0.3s ease;
}

.social-card:hover .social-handle {
    color: var(--primary);
}

/* Footer */
footer {
    background: rgba(255, 255, 255, 0.03);
        border-top: 1px solid rgba(230, 57, 70, 0.3);
        backdrop-filter: blur(10px);
        padding: 1.5rem 2rem;
    }
    
    .footer-content {
        max-width: 1200px;
        margin: 0 auto;
        display: flex;
        justify-content: space-between;
        align-items: center;
    }
    
    .footer-left {
        font-family: 'Space Grotesk', sans-serif;
        font-size: 0.9rem;
        font-weight: 600;
        color: var(--primary);
        text-transform: uppercase;
        letter-spacing: 0.05em;
    }
    
    .footer-right {
        font-family: 'Space Grotesk', sans-serif;
        font-size: 0.85rem;
    color: var(--muted);
    letter-spacing: 0.02em;
}

footer p {
    margin-bottom: 0;
}

/* Red Line with Moving White Shine */
.shine-line {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 2px;
    background: #e6394699;
    box-shadow: 0 0 15px rgba(230, 57, 70, 0.6);
    overflow: hidden;
}

.shine-line::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0%;
    width: 40%;
    height: 100%;
    background: linear-gradient(90deg,
            transparent,
            rgba(255, 255, 255, 0.6),
            transparent);
    animation: shine-oscillate 10s ease-in-out infinite;
}

@keyframes shine-oscillate {
    0% {
        left: -50%;
    }

    50% {
        left: 100%;
    }

    100% {
        left: -50%;
    }
}
/* Mobile */
@media (max-width: 768px) {
    .hamburger {
        display: flex;
    }

    nav {
        display: none;
    }

    nav.mobile-menu-open {
        display: flex;
        position: absolute;
        top: 60px;
        left: 0;
        right: 0;
        flex-direction: column;
        gap: 0;
        background: var(--bg-elevated);
        padding: 1rem;
        border-bottom: 1px solid rgba(255,255,255,0.05);
    }

    nav.mobile-menu-open .nav-link {
        padding: 1rem;
        border-bottom: 1px solid rgba(255,255,255,0.05);
    }

    h1 { font-size: 2.5rem; }
    h2 { font-size: 1.75rem; }

    .about-content {
        grid-template-columns: 1fr;
        gap: 2rem;
    }

    .hero-buttons {
        flex-direction: column;
        gap: 1rem;
    }

    .btn {
        width: 100%;
        justify-content: center;
    }

