                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .about-layout {
        grid-template-columns: 1fr;
        gap: 3rem;
        }
        
        .profile-card {
            max-width: 320px;
            margin: 0 auto;
            padding: 2rem 1.5rem;
            }
            
            .profile-card::after {
                top: -10px;
                left: -10px;
                right: -10px;
                bottom: -10px;
        }
        
        .profile-image-wrapper {
            width: 130px;
                height: 130px;
            }
            
            .profile-image-wrapper::before,
            .profile-image-wrapper::after {
                width: 6px;
                height: 6px;
            }
            
            @keyframes orbit {
                0% {
                    transform: rotate(0deg) translateX(75px) rotate(0deg);
                }
            
                100% {
                    transform: rotate(360deg) translateX(75px) rotate(-360deg);
                }
            }
            
            .about-text {
                padding-left: 1rem;
            }
            
            .about-text p {
                font-size: 1rem;
                line-height: 1.85;
            }
            
            .about-text p:first-child::first-letter {
                font-size: 2.5rem;
                margin-right: 0.5rem;
            }
            
            .highlight-tag {
                padding: 0.6rem 1.2rem;
                font-size: 0.85rem;
        }
        
        .socials-grid {
            grid-template-columns: repeat(2, 1fr);
            gap: 1rem;
        }
        
        .social-card {
            padding: 1.5rem 1rem;
        }
        
        .social-icon {
            width: 36px;
            height: 36px;
    }

    .hero {
        min-height: 90vh;
        }
        
        .hero-stats {
            flex-direction: row;
            gap: 1rem;
            padding: 1rem 1.5rem;
        }
        
        .stat-value {
            font-size: 1.5rem;
        }
        
        .stat-divider {
            height: 30px;
        }
        
        .hero-title {
            font-size: clamp(2.5rem, 15vw, 4rem);
        }
        
        .hero-badge {
            font-size: 0.75rem;
            padding: 0.4rem 1rem;
    }

    .section {
        padding: 3rem 0;
    }
    
}

